// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, dismissProjectOwnerReminder, createCollection, forceFieldSortSaveToFail, dragFieldRow } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(171000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/admin/logout`);
    await page.goto(baseUrl);

    const playwrightRequest0: Record<string, any> = {
        "email": "admin@example.com",
        "password": "admin"
    };

    await signIn(page, getValue(playwrightRequest0, "email"), getValue(playwrightRequest0, "password"));
    await dismissProjectOwnerReminder(page);
    await page.goto(`${baseUrl}/admin/settings/data-model/+`);

    const playwrightRequest1: Record<string, any> = {"collection": `sr_order_fail_${Date.now()}`};

    await createCollection(page, getValue(playwrightRequest1, "collection"));

    await forceFieldSortSaveToFail(page);
    await dragFieldRow(page, 285, 130);

    // The forced XHR failure stops PATCH /fields/<collection> from reaching the server, so
    // Directus surfaces its "Unexpected Error" dialog and rolls the optimistic reorder back.
    await expect(page.getByText('Network Error')).toBeVisible({ timeout: 10000 });

    // BUG: setSort() calls notify({ title: t('field_order_saved'), type: 'success' })
    // unconditionally after awaiting fieldsStore.updateFields(), which swallows the API error
    // instead of rethrowing it. A green "Field order saved" toast is therefore shown for a
    // reorder that was never persisted. This assertion FAILS on the current code by design.
    // The toast auto-dismisses after 3s, so wait for it to appear rather than sampling once --
    // a plain toHaveCount(0) is satisfied before the notification has rendered.
    let successToastShown = true;
    try {
        await page.locator('.notification-item.success').waitFor({ state: 'visible', timeout: 3000 });
    } catch {
        successToastShown = false;
    }
    expect(successToastShown, 'no "Field order saved" toast may be shown when the save failed').toBe(false);

    // The reorder was rolled back, so "id" is still the first field in the list.
    await expect(page.locator('.field-grid > *').first()).toContainText('id');
});
